// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = msg.sender;
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != deployer);

        // First call by the (original) admin succeeds in both versions.
        vm.prank(deployer);
        c.setOwner(newOwner);

        // General rule: the admin identity never changes, so the original
        // admin can call setOwner again successfully, for any admissible input.
        vm.prank(deployer);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

