// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // admin is the deployer (this test contract)
        vm.deal(actor, 1 ether);

        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Rule: the call succeeds ONLY for the admin; and whenever it succeeds,
        // owner becomes newOwner; whenever it reverts, owner stays the deployer.
        // Mutant: a non-admin's call succeeds (ok == true) yet owner != deployer
        // whenever newOwner != deployer, violating the rule.
        assertTrue(ok == (c.owner() == newOwner) && (!ok || c.owner() != address(0)) && (ok || c.owner() == address(this)));
    }
}

