// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner2) public {
        vm.assume(actor != msg.sender); // actor is not the admin/deployer

        // Admin legitimately transfers ownership to actor
        vm.prank(msg.sender);
        c.setOwner(actor);
        assertEq(c.owner(), actor);

        // The non-admin actor (now owner) tries to change owner again:
        // reference reverts; mutant succeeds and updates the owner.
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner2) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.owner() == actor);
    }
}
